# Generalised version of CEBE_JS's click-to-sort — that one only ever drove a
# single fixed table id; this drives every `table.mw-sort` on the page
# independently (each gets its own closure over which column/direction is
# active), because this board renders four separate sortable tables, not one.
MW_JS = """
(function(){
  function wire(table){
    var tbody = table.querySelector('tbody');
    if(!tbody) return;
    var ths = table.querySelectorAll('th[data-sort]');
    var curKey = null, asc = false;
    function apply(key){
      var rows = Array.prototype.slice.call(tbody.querySelectorAll('tr'));
      rows.sort(function(a, b){
        var av = parseFloat(a.dataset[key]);
        var bv = parseFloat(b.dataset[key]);
        if(isNaN(av)) av = asc ? Infinity : -Infinity;
        if(isNaN(bv)) bv = asc ? Infinity : -Infinity;
        return asc ? (av - bv) : (bv - av);
      });
      rows.forEach(function(r, i){
        tbody.appendChild(r);
        var rk = r.querySelector('.rk');
        if(rk) rk.textContent = i + 1;
      });
      ths.forEach(function(h){
        h.textContent = h.textContent.replace(/[\\u25B2\\u25BC]/g, '').trim();
      });
      var active = table.querySelector('th[data-sort="' + key + '"]');
      if(active) active.textContent += asc ? ' \\u25B2' : ' \\u25BC';
    }
    ths.forEach(function(th){
      th.addEventListener('click', function(){
        var key = th.dataset.sort;
        asc = (curKey === key) ? !asc : false;
        curKey = key;
        apply(key);
      });
    });
  }
  document.querySelectorAll('table.mw-sort').forEach(wire);
})();
"""


def _mw_currency_mark(code, currency_flags):
    flag = currency_flags.get(code, "🌐")
    return f'<span class="mk mk-e" aria-hidden="true">{esc(flag)}</span>'


def _mw_fx_table(fx, currency_flags, btc_price_usd=None):
    """`btc_price_usd` comes from the same board snapshot's `bitcoin.price_usd` —
    the same live figure the scarcity-lineup chart on the hub page already uses,
    so the two BTC columns here are never a second, independently-fetched price.
    Both new columns derive from `rate` (units of this currency per $1) and
    `btc_price_usd` ($ per BTC): a currency unit's sat value is
    `1e8 / (rate * btc_price_usd)` (how many of the $1-buys-`rate`-units chain's
    satoshis one unit is worth) and a whole bitcoin's price in that currency is
    `rate * btc_price_usd`. Both are None-safe — a missing/zero price (the
    snapshot's Bitcoin lineup failed to fetch that run) renders "—" and drops
    the `data-*` sort attribute entirely, so MW_JS's `isNaN` fallback sorts
    those rows last rather than crashing on a bad parseFloat."""
    rates = fx["rates"]
    rows = []
    for code in sorted(rates, key=lambda c: rates[c]):
        rate = rates[code]
        per_usd = (1.0 / rate) if rate else 0.0
        if btc_price_usd and rate:
            sats_per_unit = 1e8 / (rate * btc_price_usd)
            per_btc = rate * btc_price_usd
            btc_ds = f' data-sats="{sats_per_unit}" data-perbtc="{per_btc}"'
            sats_cell = f"{sats_per_unit:,.4f}"
            perbtc_cell = f"{per_btc:,.2f}"
        else:
            btc_ds = ""
            sats_cell = perbtc_cell = "—"
        rows.append(f"""      <tr data-rate="{rate}" data-perusd="{per_usd}"{btc_ds}>
        <td class="mw-nm"><span class="asw">{_mw_currency_mark(code, currency_flags)}
          <span class="nm"><span class="n1">{esc(code)}</span></span></span></td>
        <td>{rate:,.4f}</td>
        <td>{per_usd:,.4f}</td>
        <td>{sats_cell}</td>
        <td>{perbtc_cell}</td>
      </tr>""")
    body = "\n".join(rows)
    btc_note = (f' Bitcoin columns priced at ${btc_price_usd:,.0f}/BTC, the same live '
                'snapshot as the rates above.' if btc_price_usd else
                ' Bitcoin columns read "—" this build — the snapshot\'s bitcoin price '
                "wasn't available when this page was generated.")
    return f"""  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Currency</th>
        <th data-sort="rate" title="How many units of this currency one US dollar buys, today">Per $1</th>
        <th data-sort="perusd" title="How many US dollars one unit of this currency buys, today">$ per unit</th>
        <th data-sort="sats" title="How many satoshis (1/100,000,000 of a bitcoin) one unit of this currency buys, at today's bitcoin price">Sats per unit</th>
        <th data-sort="perbtc" title="How many units of this currency one whole bitcoin costs, today">Per ₿1</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
  </table>
  </div>
  <p class="mwbarnote">No totals row here on purpose — summing exchange rates
  across currencies has no meaningful unit; unlike every other table on this
  page, this one has nothing sensible to add up.{btc_note}</p>"""


def _mw_marketcap_table(ms, bitcoin, fx):
    """Ranks Bitcoin's total market cap against each currency's own "market
    cap" — the total value of that currency actually in existence, i.e. the
    same `broad_usd` figure (each economy's own broadest published
    money-supply aggregate, in USD at today's exchange rate) the Money
    Supply page's totals row and the hub's scarcity-lineup "Broad money" bar
    already use. Deliberately scoped to the economies THAT figure actually
    exists for — not every currency in the {fx} table above, most of which
    have no live money-supply source at all (see that page's own honest "—"
    cells) and would need a fabricated number to appear in a ranking here.
    Built 2026-09-08 at Michael's request ("show where Bitcoin ranks in
    market cap... list and rank all the other currencies the same way").

    ⚡ Same day: gained two more sortable columns, `volatility_pct` (annualized
    stdev of daily log returns — the exact same statistic for every fiat row
    AND Bitcoin, from `fetch_fx_volatility()`/`fetch_bitcoin_market_stats()` in
    the fetcher) and `broad_yoy_pct` (this economy's own broadest aggregate's
    year-over-year growth in ITS OWN currency — a currency's "debasement
    rate" — from `_money_broad_yoy_pct()`/`_btc_annual_issuance_pct()`,
    Bitcoin's own row computed exactly from the halving schedule rather than
    fetched). Both are None-safe: a row with no resolvable figure (China's
    hand-curated values have no queryable history; India's RBI scrape wasn't
    extended; USD has no volatility against itself, being this whole page's
    numeraire) renders "—" and sorts last, same convention as every other
    honest gap on this board — never a fabricated number.

    ⚡ 2026-09-09 — one more: `turnover_usd`, each currency's implied daily FX
    trading volume, from the curated BIS Triennial Survey shares
    (`fetch_fx_turnover()` — a periodic SURVEY, refreshed once every three
    years like the gold-reserve tonnages, not a live feed) alongside
    Bitcoin's own live 24h volume (`fetch_bitcoin_market_stats()`'s second
    return value, off the SAME CoinGecko call the volatility column already
    makes — no extra request). Resolves for all 12 currencies here (the BIS
    survey happens to cover exactly this board's roster), so unlike the
    other two new columns this one has no "—" gaps on the fiat side."""
    entries = []
    for r in ms.get("rows", []):
        cap = r.get("broad_usd")
        if cap is None:
            continue
        entries.append({"flag": r["flag"], "name": r["area"], "code": r["currency"],
                         "cap": cap * 1e9, "is_btc": False,
                         "vol": r.get("volatility_pct"), "yoy": r.get("broad_yoy_pct"),
                         "turn": r.get("turnover_usd")})
    btc_cap = (bitcoin or {}).get("market_cap_usd")
    if btc_cap:
        entries.append({"flag": "₿", "name": "Bitcoin", "code": "BTC",
                         "cap": btc_cap, "is_btc": True,
                         "vol": (bitcoin or {}).get("volatility_pct"),
                         "yoy": (bitcoin or {}).get("broad_yoy_pct"),
                         "turn": (bitcoin or {}).get("turnover_usd")})
    entries.sort(key=lambda e: e["cap"], reverse=True)
    n = len(entries)
    if n == 0:
        return ""
    btc_rank = next((i + 1 for i, e in enumerate(entries) if e["is_btc"]), None)
    n_currencies = sum(1 for e in entries if not e["is_btc"])

    rows = []
    for i, e in enumerate(entries):
        cls = ' class="mw-btcrow"' if e["is_btc"] else ""
        ds = {"cap": e["cap"]}
        if e["yoy"] is not None:
            ds["yoy"] = e["yoy"]
        if e["vol"] is not None:
            ds["vol"] = e["vol"]
        if e["turn"] is not None:
            ds["turn"] = e["turn"]
        ds_attrs = " ".join(f'data-{k}="{v}"' for k, v in ds.items())
        yoy_cell = pct(e["yoy"])
        vol_cell = "—" if e["vol"] is None else f"{e['vol']:.2f}%"
        turn_cell = "—" if e["turn"] is None else money_full(e["turn"])
        rows.append(f"""      <tr{cls} {ds_attrs}>
        <td class="rk">{i + 1}</td>
        <td class="mw-nm"><span class="asw"><span class="mk mk-e" aria-hidden="true">{esc(e['flag'])}</span>
          <span class="nm"><span class="n1">{esc(e['name'])}</span>
          <span class="n2">{esc(e['code'])}</span></span></span></td>
        <td class="mc">{money_full(e['cap'])}</td>
        <td>{yoy_cell}</td>
        <td>{vol_cell}</td>
        <td>{turn_cell}</td>
      </tr>""")
    body = "\n".join(rows)

    btc_line = (f' Bitcoin lands at <b class="mwlede-hl">#{btc_rank}</b> of {n} on this '
                f'list today.' if btc_rank else "")
    fx_n = len(fx.get("rates", {})) if fx else 0
    return f"""  <h2 class="mwh2">Where Bitcoin ranks by market cap</h2>
  <p class="mwsub">Each economy's own broadest published money-supply aggregate — the
  total value of that currency actually in existence, at today's exchange rate — set
  against Bitcoin's total market cap, ranked together.{btc_line} Scoped to the
  {n_currencies} economies the <a href="money-worldwide-money-supply.html">Money Supply
  page</a> has a real, live figure for today — most of the {fx_n} currencies in the
  exchange-rate table above have no live money-supply source yet (see that page's own
  "—" cells), so they're left off this ranking rather than shown with a fabricated
  number. Click any column to re-sort.</p>
  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Rank</th>
        <th>Currency</th>
        <th data-sort="cap" title="Each economy's own broadest published money-supply aggregate, in US dollars at today's exchange rate — Bitcoin's own total market cap for comparison">Market cap</th>
        <th data-sort="yoy" title="This economy's own broadest money-supply aggregate, year-over-year, in its OWN currency (not USD — a currency's exchange-rate move against the dollar is a different fact from how much more of it now exists) — a currency's own debasement rate. Bitcoin's figure is computed exactly from its halving schedule, not fetched.">Supply growth (YoY)</th>
        <th data-sort="vol" title="Annualized volatility — the standard deviation of daily log returns over the trailing year, computed the same way for every fiat currency and for Bitcoin (Frankfurter's ECB reference rates; CoinGecko's daily close for Bitcoin)">Volatility</th>
        <th data-sort="turn" title="Daily trading volume — for fiat, each currency's implied share of the BIS Triennial Central Bank Survey's global FX turnover (April 2025, a periodic survey, refreshed once every three years, not a live feed); for Bitcoin, live 24h spot volume across the exchanges CoinGecko tracks. Two different measurement methods for the same underlying question — see the note below.">Daily trading volume</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
  </table>
  </div>
  <p class="mwbarnote">"Market cap" here means the total value of each currency
  actually in existence (M2/M3/M4-class, whichever aggregate an economy's own central
  bank considers its broadest published one) — the closest fiat equivalent to a
  fixed-supply asset's market cap, and the same figure used in the "Broad money" bar on
  the <a href="money-worldwide.html#how-this-board-is-made">Money Worldwide hub</a>'s
  scarcity chart and the <a href="money-worldwide-money-supply.html">Money Supply
  page</a>'s own totals row. "Supply growth" and "Volatility" read "—" where no real,
  live source resolves one (China's money-supply figures are hand-curated from a press
  release with no queryable history behind them; USD has no volatility against itself,
  being this whole page's own numeraire) — never a filled-in guess. "Daily trading
  volume" mixes two genuinely different measurements on purpose, not by oversight: the
  fiat figures are a currency's implied share of a periodic survey's global total (BIS
  Triennial Survey, April 2025 — a snapshot from central banks and dealers, taken once
  every three years), while Bitcoin's is a live daily figure from spot exchanges. A
  currency's real trading activity moves throughout each three-year gap; Bitcoin's does
  not sit still for the comparison the way a survey year does.</p>"""


def _mw_money_supply_table(ms):
    rows = []
    for r in ms["rows"]:
        def cell(usd_b, native_b, native_ccy, date):
            if usd_b is None:
                return "<td class=\"mw-sub\">—</td>"
            native_s = (f"{native_b:,.1f} {native_ccy}B as of {esc(date)}"
                        if native_ccy != "USD" and native_b is not None else esc(date or ""))
            return f'<td title="{native_s}">{money_full(usd_b * 1e9)}</td>'
        c0 = cell(r.get("usd_m0"), r.get("m0"), r["currency"], r.get("m0_date"))
        c1 = cell(r.get("usd_m1"), r.get("m1"), r["currency"], r.get("m1_date"))
        c2 = cell(r.get("usd_m2"), r.get("m2"), r["currency"], r.get("m2_date"))
        c3 = cell(r.get("usd_m3"), r.get("m3"), r["currency"], r.get("m3_date"))
        # Sort keys live on the <tr> itself (see MW_JS — it reads a.dataset[key]
        # off each row), one attribute per sortable column, matching CEBE_JS's
        # own established convention.
        ds = {"m0": r.get("usd_m0"), "m1": r.get("usd_m1"),
              "m2": r.get("usd_m2"), "m3": r.get("usd_m3")}
        ds_attrs = " ".join(f'data-{k}="{v}"' for k, v in ds.items() if v is not None)
        rows.append(f"""      <tr {ds_attrs}>
        <td class="mw-nm"><span class="asw"><span class="mk mk-e" aria-hidden="true">{esc(r['flag'])}</span>
          <span class="nm"><span class="n1">{esc(r['area'])}</span>
          <span class="mw-sub">{esc(r['source'])}</span></span></span></td>
        {c0}
        {c1}
        {c2}
        {c3}
      </tr>""")
    body = "\n".join(rows)
    tot0 = sum(r["usd_m0"] for r in ms["rows"] if r.get("usd_m0") is not None)
    tot1 = sum(r["usd_m1"] for r in ms["rows"] if r.get("usd_m1") is not None)
    tot2 = sum(r["usd_m2"] for r in ms["rows"] if r.get("usd_m2") is not None)
    tot3 = sum(r["usd_m3"] for r in ms["rows"] if r.get("usd_m3") is not None)
    eu_row = next((r for r in ms["rows"] if r["area"] == "Euro area"), {})
    eu_m0_date = eu_row.get("m0_date") or "date unknown"
    return f"""  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Economy</th>
        <th data-sort="m0" title="Physical currency + bank reserves at the central bank — the narrowest aggregate, an M0-class figure">Monetary base (M0-class)</th>
        <th data-sort="m1" title="Currency in circulation + demand deposits">M1</th>
        <th data-sort="m2" title="M1 + savings/small time deposits">M2</th>
        <th data-sort="m3" title="The broadest aggregate this economy itself publishes — M3 for most rows here, or another headline aggregate shown in this column where that's what a central bank calls its own broadest tier (e.g. the UK's M4); the US does not publish a distinct M3">M3</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
    <tfoot>
      <tr>
        <td class="mw-nm trstot-l">Total (at today's exchange rate)</td>
        <td>{money_full(tot0 * 1e9) if tot0 else '—'}</td>
        <td>{money_full(tot1 * 1e9) if tot1 else '—'}</td>
        <td>{money_full(tot2 * 1e9) if tot2 else '—'}</td>
        <td>{money_full(tot3 * 1e9) if tot3 else '—'}</td>
      </tr>
    </tfoot>
  </table>
  </div>
  <p class="mwbarnote">Euro area monetary base (M0) is the one figure on this whole board that
  is hand-curated rather than live-queried. The Eurosystem calls it "Base money" (banknotes in
  circulation plus bank reserves at the ECB — the same idea as the Fed's monetary base) and
  states it in plain English every week in its own Consolidated Financial Statement press
  release — but the underlying series lives in a different ECB dataset (Internal Liquidity
  Management, the Eurosystem's own weekly financial statement) from the one used for M1/M2/M3
  here (Balance Sheet Items), and a real, substantial attempt at a live keyless query against
  it — the exact item code plus roughly 155 real dimension-value combinations tried against
  the ECB's own API — found no working query. So this figure is read by hand from that weekly
  release ({esc(eu_m0_date)}) and refreshed periodically rather than every build, the same
  posture this board already takes with gold reserves — its DOLLAR value still recomputes
  from today's live exchange rate like every other cell here, only the underlying euro figure
  itself is periodic. The totals row above therefore blends one periodic figure into an
  otherwise-live row.</p>"""


def _mw_reserves_fx_table(reserves_fx):
    rows = []
    for r in reserves_fx["rows"]:
        usd_b = r["usd_m"] / 1000.0
        date_key = (r.get("as_of") or "").replace("-", "") or "0"
        rows.append(f"""      <tr data-usd="{usd_b}" data-date="{date_key}">
        <td class="mw-nm"><span class="asw"><span class="mk mk-e" aria-hidden="true">{esc(r['flag'])}</span>
          <span class="nm"><span class="n1">{esc(r['area'])}</span></span></span></td>
        <td>{money_full(r['usd_m'] * 1e6)}</td>
        <td class="ao">{esc(r.get('as_of') or '—')}</td>
      </tr>""")
    body = "\n".join(rows)
    n = len(reserves_fx["rows"])
    return f"""  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Economy</th>
        <th data-sort="usd" title="Foreign exchange + SDRs + IMF reserve position — excludes gold, shown separately below">Reserves, excl. gold</th>
        <th data-sort="date" title="The most recent month this economy's own reporting covers">As of</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
    <tfoot>
      <tr>
        <td class="mw-nm trstot-l">Total — {n} economies</td>
        <td>{money_full(reserves_fx["total_usd_m"] * 1e6)}</td>
        <td></td>
      </tr>
    </tfoot>
  </table>
  </div>"""


def _mw_gold_table(gold):
    rows = []
    for r in gold["rows"]:
        rows.append(f"""      <tr data-tonnes="{r['tonnes']}" data-usd="{r['usd']}">
        <td class="mw-nm"><span class="asw"><span class="mk mk-e" aria-hidden="true">{esc(r['flag'])}</span>
          <span class="nm"><span class="n1">{esc(r['country'])}</span></span></span></td>
        <td>{r['tonnes']:,} tons</td>
        <td>{money_full(r['usd'])}</td>
      </tr>""")
    body = "\n".join(rows)
    n = len(gold["rows"])
    return f"""  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Country</th>
        <th data-sort="tonnes" title="Official-sector gold reserves, in metric tons">Gold reserves</th>
        <th data-sort="usd" title="Tons × troy ounces per ton × today's gold price">Value, today's price</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
    <tfoot>
      <tr>
        <td class="mw-nm trstot-l">Total — {n} countries shown</td>
        <td>{gold['total_tonnes']:,} tons</td>
        <td>{money_full(gold['total_usd'])}</td>
      </tr>
    </tfoot>
  </table>
  </div>
  <p class="mwbarnote">These {n} are a curated top slice, not every reporting
  country — the World Gold Council's own estimate for ALL central banks and
  the IMF together is ≈{gold.get('world_official_tonnes_estimate', 0):,} tons,
  well above the {gold['total_tonnes']:,} tons summed here.</p>"""


def _mw_debt_gdp_table(dg):
    rows = []
    for r in dg["rows"]:
        name, flag = _mw_flag_name(r["area"])
        debt_b = r.get("debt_usd_b")
        debt_pct = r.get("debt_pct_gdp")
        ds = {"gdp": r["gdp_usd_b"]}
        if debt_pct is not None:
            ds["pct"] = debt_pct
        if debt_b is not None:
            ds["debt"] = debt_b
        ds_attrs = " ".join(f'data-{k}="{v}"' for k, v in ds.items())
        rows.append(f"""      <tr {ds_attrs}>
        <td class="mw-nm"><span class="asw"><span class="mk mk-e" aria-hidden="true">{esc(flag)}</span>
          <span class="nm"><span class="n1">{esc(name)}</span></span></span></td>
        <td>{money_full(r['gdp_usd_b'] * 1e9)}</td>
        <td class="{'mw-r' if (debt_pct or 0) >= 100 else ''}">
          {('%.1f%%' % debt_pct) if debt_pct is not None else '—'}</td>
        <td>{money_full(debt_b * 1e9) if debt_b is not None else '—'}</td>
      </tr>""")
    body = "\n".join(rows)
    tot_gdp = sum(r["gdp_usd_b"] for r in dg["rows"])
    tot_debt = sum(r["debt_usd_b"] for r in dg["rows"] if r.get("debt_usd_b") is not None)
    weighted_pct = (tot_debt / tot_gdp * 100.0) if tot_gdp else None
    return f"""  <div class="tw">
  <table class="board mw-sort">
    <thead>
      <tr>
        <th>Economy</th>
        <th data-sort="gdp" title="GDP, current prices — IMF World Economic Outlook, {esc(dg['rows'][0]['year']) if dg['rows'] else ''} estimate">GDP</th>
        <th data-sort="pct" title="General government gross debt, as a share of that economy's own GDP">Govt. debt (% of GDP)</th>
        <th data-sort="debt" title="GDP × debt-to-GDP — an implied dollar figure, not separately published by the IMF">Govt. debt ($, implied)</th>
      </tr>
    </thead>
    <tbody>
{body}
    </tbody>
    <tfoot>
      <tr>
        <td class="mw-nm trstot-l">Total — all {dg['n_countries_total']} economies IMF covers</td>
        <td>{money_full(tot_gdp * 1e9)}</td>
        <td>{('%.1f%% (weighted avg.)' % weighted_pct) if weighted_pct is not None else '—'}</td>
        <td>{money_full(tot_debt * 1e9)}</td>
      </tr>
    </tfoot>
  </table>
  </div>
  <p class="mwbarnote">Every economy the IMF's World Economic Outlook covers is listed above —
  no top-N cutoff (2026-09-08, Michael's call). The totals row is a straight sum of the
  {dg['n_countries_total']} rows shown; it may not land exactly on the World GDP figure
  quoted elsewhere on this board ({money_full(dg['world_gdp_usd_b'] * 1e9)}), because that
  figure prefers the IMF's own official WEOWORLD aggregate over a sum of member economies
  when the IMF publishes one — a small, expected methodology difference, not a bug.</p>"""


def _mw_scarcity_bar(item, max_usd, colour):
    width_pct = max(1.5, (item["usd"] / max_usd) * 100.0) if max_usd else 1.5
    return f"""    <div class="mwbarrow">
      <div class="mwbl">{esc(item['label'])}</div>
      <div class="mwbartrack"><div class="mwbarfill" style="width:{width_pct:.2f}%;background:{colour}"></div></div>
      <div class="mwbv">{money_full(item['usd'])}</div>
      <div class="mwbarnote">{esc(item['note'])}</div>
    </div>"""


# NOTE: this dict is built at import time when ACCENT is already a plain
# string constant, not the "__ACCENT__" placeholder — that placeholder only
# gets substituted inside CSS/JS blocks by _shell(), never inside body HTML,
# so a bar drawn directly in the body must use the real value here.
# Matched by PREFIX, not exact string — the "Broad money" label carries a
# live economy count since 2026-09-08 ("Broad money — 7 economies with live
# data"), which would otherwise never match an exact key and silently fall
# through to the default grey.
_MW_LINEUP_COLOURS = (
    ("Broad money", "#5eb3d6"),
    ("Gold — all above-ground supply", "#c9b45e"),
    ("Bitcoin — total market cap", ACCENT),
)


def _mw_lineup_colour(label):
    return next((c for prefix, c in _MW_LINEUP_COLOURS if label.startswith(prefix)), "#8f8fd6")


def _mw_scarcity_chart(bitcoin):
    lineup = bitcoin.get("lineup") or []
    if not lineup:
        return ""
    max_usd = max(item["usd"] for item in lineup)
    bars = "\n".join(
        _mw_scarcity_bar(item, max_usd, _mw_lineup_colour(item["label"]))
        for item in lineup)
    return f"""  <h2 class="mwh2">The scarcity lineup</h2>
  <p class="mwsub">Three figures, side by side, at the same scale — deliberately NOT summed
  into one number, because the whole point is the CONTRAST between them. Fiat money supply can
  be and regularly is expanded by policy choice. Gold's supply grows too, just slowly — new
  mining adds roughly 1.5% to the above-ground stock in a typical year. Bitcoin's supply is
  fixed by its own consensus rule at 21 million coins, full stop, growing toward that cap on a
  published, unchangeable schedule and never past it. (World GDP appears elsewhere on this
  page, not here — it measures a YEAR of economic output, not a stock of money or value, so
  mixing it into this particular comparison would answer a different question than the one
  this chart is asking.)</p>
  <div class="mwscarcity">
{bars}
  </div>
  <p class="mwcaveat">⚠️ The "Broad money" bar is a sum across different countries' own
  currencies, converted to dollars at TODAY's exchange rate. That means it moves for two
  completely different reasons that look identical on this chart: real growth in the money
  supply, AND swings in the dollar's own exchange rate against the euro. A stronger dollar
  alone would shrink this bar even if not one additional euro or dollar were ever printed —
  don't read a change here as evidence of printing without checking the FX rate first.</p>"""


def _mw_methods_panel(board):
    gold = board.get("gold") or {}
    ms_resolved, ms_total = _mw_ms_counts(board.get("money_supply") or {})
    return f"""  <div class="panel" id="how-this-board-is-made">
    <h2>How this board is made, and what it deliberately is not</h2>
    <p><b>Exchange rates</b> are the European Central Bank's own daily reference rates,
    reached through a free keyless proxy (Frankfurter) rather than a third-party estimate —
    the same rates the IMF itself references when it revalues the Special Drawing Right every
    five years (see <a href="untangling-bis-imf-world-bank.html">the Ledger's own entry on
    what the IMF, the BIS and the World Bank each actually do</a>).</p>
    <p><b>Money supply</b> covers {ms_resolved} economies with real, current, live-queried
    figures — the United States (Federal Reserve H.6), the Euro area (European Central Bank),
    Canada (Bank of Canada Valet API), Switzerland (SNB Data Portal), Brazil (Banco Central do
    Brasil SGS API), the United Kingdom (Bank of England IADB) and Norway (Statistics Norway
    StatBank) — not all ~190 IMF members, and coverage per economy is genuinely uneven (Norway
    publishes all four aggregates; the US and UK publish only some). That unevenness is a real
    limitation, not laziness: a real, hands-on hunt for one templated source that mirrors many
    countries' money supply at once (the obvious next step after FRED's own templated reserve-
    series mirror worked) found the pattern genuinely exists on FRED (OECD's discontinued Main
    Economic Indicators series) — but every country in that family stopped updating years ago
    (most in 2023, some back to 2018), so none of it is used here. A further
    {ms_total - ms_resolved} economies (China, India, Japan, South Korea, Mexico, Turkey, South
    Africa, Australia, Denmark) were seriously investigated and are shown with blank cells and
    their own source-note rather than silently dropped — each hit a real, named obstacle (a
    discontinued mirror, an API that requires a registered key, a genuinely live source only
    available as a spreadsheet). The Euro area's monetary base ("Base money" in the ECB's own
    terminology) is the one figure on
    this whole board that is hand-curated rather than live-queried — it genuinely exists and the
    ECB states it in plain English every week, but in a different ECB dataset than the one used
    for its own M1/M2/M3 (which, unlike M0, ARE reachable the same live keyless way as everything
    else here) — see the Money Supply page's own note for the full trail, and
    <code>tools/fetch_money_worldwide.py</code>'s own dated research log for every economy's
    individual story.</p>
    <p><b>Reserves (excl. gold)</b> are curated to the {len(board.get('reserves_fx', {}).get('rows', []))}
    largest holders that a real, live, keyless mirror of IMF's own International Financial
    Statistics reserve series actually covers — several economies that would belong on this
    list (the Euro area as a bloc, Switzerland, Hong Kong, Singapore) either have no matching
    mirror or one that stopped updating years ago, and are left off rather than shown stale.</p>
    <p><b>Gold reserves</b> are a curated, dated list of the {len(gold.get('rows', []))} largest
    official holders (World Gold Council, compiled from IMF reporting) — central banks report
    this quarterly at best, so this is refreshed by hand periodically rather than pulled live
    every build. It is priced at today's live gold quote (shared with <a href="board.html">the
    Asset Board</a>).</p>
    <p><b>Global debt &amp; GDP</b> is the one section pulled directly from an IMF system that
    actually serves real data — the DataMapper API behind imf.org's own public data
    visualizations — across essentially every economy the IMF's World Economic Outlook covers.
    The dollar debt figures are IMPLIED (GDP × the IMF's own published debt-to-GDP ratio), not
    a separately published dollar series.</p>
    <p>Nothing here is investment advice, and none of the institutions named on this page have
    endorsed it or are affiliated with it.</p>
  </div>"""


def _mw_load_currency_flags():
    seed_path = os.path.join(ROOT, "source", "finance", "money_worldwide_seed.json")
    if os.path.exists(seed_path):
        try:
            with open(seed_path, encoding="utf-8") as fh:
                return (json.load(fh) or {}).get("currency_flags", {})
        except (ValueError, OSError):
            pass
    return {}


def _mw_broad_money_usd(ms):
    """Sum of each economy's own broadest published aggregate (`broad_usd`,
    already in billions of dollars) — the same figure the scarcity chart's
    "Broad money" bar uses, recomputed here so the hub card doesn't need
    `bitcoin` to exist just to show a money-supply headline."""
    return sum(r.get("broad_usd") or 0.0 for r in ms.get("rows", [])) * 1e9


def _mw_ms_counts(ms):
    """(resolved, total) economy counts — `n_resolved`/`n_total` when the
    fetcher wrote them (2026-09-08+), else derived from the rows themselves
    (a row with every m0-m3 cell None is one of the honest blank-cell
    placeholders — see `_unresolved_money_row` in the fetcher)."""
    if "n_resolved" in ms and "n_total" in ms:
        return ms["n_resolved"], ms["n_total"]
    rows = ms.get("rows", [])
    resolved = sum(1 for r in rows if any(r.get(k) is not None for k in ("m0", "m1", "m2", "m3")))
    return resolved, len(rows)


def _mw_hub_card(key, value_html, sub_html):
    meta = MW_SECTIONS[key]
    return (f'    <a class="trsbox" href="{meta["file"]}">'
            f'<div class="tb-top"><span class="tb-i">{meta["icon"]}</span>'
            f'<span class="tb-t">{esc(meta["title"])} →</span></div>'
            f'<div class="tb-v">{value_html}</div>'
            f'<div class="tb-s">{sub_html}</div>'
            f'<p class="tb-d">{esc(meta["blurb"])}</p></a>')


def _mw_hub_cards(board):
    fx, ms = board.get("fx"), board.get("money_supply")
    reserves_fx, gold = board.get("reserves_fx"), board.get("gold")
    debt_gdp = board.get("debt_gdp")
    cards = []
    if fx:
        cards.append(_mw_hub_card(
            "exchange-rates", f'{len(fx["rates"])} currencies',
            f'vs. US dollar · {esc(fx.get("date") or "today")}'))
    if ms:
        n_resolved, n_total = _mw_ms_counts(ms)
        sub = (f'{n_resolved} economies with live data · {n_total} tracked · combined broad money'
               if n_resolved < n_total else f'{n_total} economies · combined broad money')
        cards.append(_mw_hub_card("money-supply", money_full(_mw_broad_money_usd(ms)), sub))
    if reserves_fx:
        cards.append(_mw_hub_card(
            "reserves", money_full(reserves_fx["total_usd_m"] * 1e6),
            f'{len(reserves_fx["rows"])} economies'))
    if gold:
        cards.append(_mw_hub_card(
            "gold", money_full(gold["total_usd"]),
            f'{gold["total_tonnes"]:,} tons across {len(gold["rows"])} countries'))
    if debt_gdp:
        world_pct = debt_gdp.get("world_debt_pct_gdp")
        cards.append(_mw_hub_card(
            "debt-gdp", money_full(debt_gdp["world_gdp_usd_b"] * 1e9),
            f'world debt-to-GDP {("%.1f%%" % world_pct) if world_pct is not None else "—"} '
            f'· all {debt_gdp["n_countries_total"]} economies shown'))
    return "\n".join(cards)


def build_money_worldwide_hub(board):
    """The top of the tree: one card per section (linking into that section's
    own full page — see build_money_worldwide_section), plus the scarcity
    lineup chart and the methodology panel — SPLIT 2026-09-08 (Michael's
    call: "too much data on that one page"), same hub/sub-page pattern as
    the Treasuries board (build_treasuries_hub).

    The chart and the methods panel deliberately stay HERE rather than
    moving onto any one section's page: the chart is a cross-section
    synthesis (money supply, gold AND Bitcoin, side by side, on purpose —
    see _mw_scarcity_chart) that doesn't belong to a single section, and the
    methods panel documents every section's sourcing at once — splitting
    either across five pages would mean repeating it five times or picking
    one arbitrary page to own it. Each section page still gets its own
    caveats inline (the fx table's "no totals row" note, the gold table's
    world-estimate note, etc.) and a link back to this fuller methodology.
    """
    bitcoin = board.get("bitcoin")
    cards = _mw_hub_cards(board)

    btc_line = ""
    if bitcoin and bitcoin.get("market_cap_usd"):
        btc_line = (f' Bitcoin\'s own market cap today is '
                     f'<span class="mwlede-hl">{money_full(bitcoin["market_cap_usd"])}</span>'
                     f' — currently #{bitcoin.get("btc_rank", "?")} on '
                     f'<a href="board.html">the Asset Board</a>.')

    scarcity = _mw_scarcity_chart(bitcoin) if bitcoin else ""

    desc = ("Exchange rates, money supply, reserves and gold, and global debt & GDP — "
            "with Bitcoin's own market cap set against every one of them.")
    body = f"""  <p class="trskicker"><a href="untangling-bis-imf-world-bank.html">See also: Untangling
    the BIS, the IMF, and the World Bank →</a></p>
  <h1 class="btitle">Money Worldwide</h1>
  <p class="lede">Four numbers that don't normally sit on the same page: what a dollar buys
  elsewhere, how much money actually exists, who holds the world's reserves, and how big the
  world's economy and its government debt actually are.{btc_line}</p>
  <p class="stamp">Updated {esc(board.get('generated', '—'))}</p>
  <div class="trsboxes">
{cards}
  </div>
{scarcity}
{_mw_methods_panel(board)}
{_comment_box("Money Worldwide", "%smoney-worldwide.html" % BASE_URL)}
  <p class="backlink"><a href="index.html">← Back to the front page</a></p>
"""
    return _shell(title="Money Worldwide — exchange rates, money supply, reserves, debt & GDP — %s" % SITE_NAME,
                  desc=desc, url="%smoney-worldwide.html" % BASE_URL, active="money-worldwide",
                  body=body, extra_css=TREASURY_CSS + MW_CSS, extra_js=MW_JS)


def build_money_worldwide_section(board, key):
    """One section's own full table, on its own page — the Money Worldwide
    counterpart to build_treasuries_category. `key` is one of
    MW_SECTION_ORDER. The board-wide methodology panel stays on the hub
    (see build_money_worldwide_hub's docstring); this page links back to it
    rather than repeating all five sections' sourcing notes here."""
    meta = MW_SECTIONS[key]
    fx, ms = board.get("fx"), board.get("money_supply")
    reserves_fx, gold = board.get("reserves_fx"), board.get("gold")
    debt_gdp = board.get("debt_gdp")

    if key == "exchange-rates":
        intro = (f'  <p class="mwsub">{len(fx["rates"])} currencies against the US '
                  f'dollar, {esc(fx.get("date") or "today")} — European Central Bank '
                  'reference rates, plus what each currency is worth in bitcoin, both '
                  'ways. Click any column to sort.</p>')
        bitcoin = board.get("bitcoin")
        btc_price = (bitcoin or {}).get("price_usd")
        table = _mw_fx_table(fx, _mw_load_currency_flags(), btc_price)
        if ms:
            table += "\n" + _mw_marketcap_table(ms, bitcoin, fx)
    elif key == "money-supply":
        ms_resolved, ms_total = _mw_ms_counts(ms or {})
        intro = (f'  <p class="mwsub">How much money actually exists, by aggregate — '
                  f'narrowest (M0-class) to broadest each economy publishes. '
                  f'{ms_resolved} of {ms_total} economies tracked here have a real, live figure '
                  f'today; the rest show "—" with their own source-note under the area name — '
                  f'a genuinely investigated economy with no working live source yet, not a '
                  f'guess or a silent drop. Click any column to sort.</p>')
        table = _mw_money_supply_table(ms)
    elif key == "reserves":
        intro = ('  <p class="mwsub">Foreign exchange + SDRs + IMF reserve position, by '
                  'economy — shown separately from gold (its own page) so a reserve '
                  'stockpile\'s hard-asset share never gets obscured by summing the two '
                  'together. Click any column to sort.</p>')
        table = _mw_reserves_fx_table(reserves_fx)
    elif key == "gold":
        intro = ('  <p class="mwsub">Official-sector gold reserves by country, priced at '
                  'today\'s live gold quote — shown separately from foreign-exchange '
                  'reserves (its own page). Click any column to sort.</p>')
        table = _mw_gold_table(gold)
    else:  # debt-gdp
        intro = (f'  <p class="mwsub">All {debt_gdp["n_countries_total"]} economies the IMF '
                  'covers, ranked by GDP — with each one\'s general government gross debt as '
                  'a share of its own GDP. Click any column to sort.</p>')
        table = _mw_debt_gdp_table(debt_gdp)

    desc = f"{meta['title']} — {meta['blurb']} Part of the Money Worldwide board."
    kicker = ('  <p class="trskicker"><a href="money-worldwide.html">'
              '<span class="mw-kicker-icon">💰</span> Money Worldwide</a></p>')
    body = f"""{kicker}
  <h1 class="btitle"><span class="mw-page-icon">{meta['icon']}</span> {esc(meta['title'])}</h1>
{intro}
  <p class="stamp">Updated {esc(board.get('generated', '—'))} · see <a
    href="money-worldwide.html#how-this-board-is-made">how this whole board is made →</a></p>
{table}
{_comment_box(meta["title"] + " — Money Worldwide", "%s%s" % (BASE_URL, meta["file"]))}
  <p class="backlink"><a href="money-worldwide.html">← All Money Worldwide sections</a></p>
"""
    return _shell(title=f"{meta['title']} — Money Worldwide — {SITE_NAME}",
                  desc=desc, url="%s%s" % (BASE_URL, meta["file"]), active="money-worldwide",
                  body=body, extra_css=TREASURY_CSS + MW_CSS, extra_js=MW_JS)


def build_sitemap(entries, tags):
    """A sitemap is not optional here — it IS the discovery plan.

    Nothing links to this publication from outside, so a crawler has no path in.
    robots.txt advertises this file. Tag pages appear only once they carry
    TAG_INDEX_MIN entries; submitting a page we have marked noindex would be
    asking Google to index something we told it not to.
    """
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    urls = [(BASE_URL, today), ("%sboard.html" % BASE_URL, today),
            ("%sbitcoin.html" % BASE_URL, today), ("%streasuries.html" % BASE_URL, today),
            ("%scrypto.html" % BASE_URL, today), ("%smoney-worldwide.html" % BASE_URL, today),
            ("%sask.html" % BASE_URL, today)]
    urls += [("%s%s" % (BASE_URL, meta["file"]), today)
             for meta in TREASURY_CATEGORIES.values()]
    urls += [("%s%s" % (BASE_URL, meta["file"]), today)
             for meta in MW_SECTIONS.values()]
    for e in entries:
        urls.append(("%s%s" % (BASE_URL, e["file"]), e["date"].isoformat()))
    for tag, es in sorted(tags.items()):
        if len(es) >= TAG_INDEX_MIN:
            urls.append(("%stag-%s.html" % (BASE_URL, blogkit.tag_slug(tag)),
                         max(x["date"] for x in es).isoformat()))
    body = "\n".join(
        "  <url>\n    <loc>%s</loc>\n    <lastmod>%s</lastmod>\n  </url>" % u
        for u in urls)
    return ('<?xml version="1.0" encoding="UTF-8"?>\n'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
            + body + "\n</urlset>\n")


def main():
    include_drafts = "--drafts" in sys.argv

    if not os.path.exists(SRC):
        sys.exit("no source/finance/asset_board.json — run tools/fetch_asset_board.py first")
    with open(SRC, encoding="utf-8") as fh:
        board = json.load(fh)
    if not (board.get("assets") or []):
        sys.exit("asset_board.json has no assets — refusing to build an empty board")

    # The Bitcoin board is optional by design. A missing or unreadable stats file
    # costs exactly one page and leaves the rest of the publication building —
    # the alternative, failing the whole build because mempool.space had a bad
    # night, would take the writing offline over a dashboard.
    stats = None
    if os.path.exists(BTC_SRC):
        try:
            with open(BTC_SRC, encoding="utf-8") as fh:
                stats = json.load(fh)
        except (ValueError, OSError) as exc:
            print("  ! bitcoin_stats.json unreadable (%s) — skipping the Bitcoin "
                  "board" % exc, file=sys.stderr)

    entries = load_entries(include_drafts=include_drafts)
    live = [e for e in entries if not e["draft"]]
    check_entries(entries)

    # The Treasuries board is optional by the same contract as the Bitcoin board:
    # missing or unreadable JSON costs exactly its own pages, never the rest of
    # the publication. Loaded before the front page so its card can appear there.
    treasuries = None
    if os.path.exists(TREASURIES_SRC):
        try:
            with open(TREASURIES_SRC, encoding="utf-8") as fh:
                treasuries = json.load(fh)
        except (ValueError, OSError) as exc:
            print("  ! treasuries.json unreadable (%s) — skipping the Treasuries "
                  "board" % exc, file=sys.stderr)

    # The Crypto Heat Map is optional by the same contract as the other boards.
    # Loaded before the front page so its card can appear there, same as Treasuries.
    crypto = None
    if os.path.exists(CRYPTO_SRC):
        try:
            with open(CRYPTO_SRC, encoding="utf-8") as fh:
                crypto = json.load(fh)
        except (ValueError, OSError) as exc:
            print("  ! crypto_heatmap.json unreadable (%s) — skipping the Crypto "
                  "Heat Map" % exc, file=sys.stderr)

    # The Money Worldwide board is optional by the same contract as the other
    # boards. Loaded before the front page so its card can appear there.
    money_worldwide = None
    if os.path.exists(MONEY_WORLDWIDE_SRC):
        try:
            with open(MONEY_WORLDWIDE_SRC, encoding="utf-8") as fh:
                money_worldwide = json.load(fh)
        except (ValueError, OSError) as exc:
            print("  ! money_worldwide.json unreadable (%s) — skipping the Money "
                  "Worldwide board" % exc, file=sys.stderr)

    tags = tag_index(live)
    os.makedirs(os.path.join(OUT, "img"), exist_ok=True)
    _render_default_card(os.path.join(OUT, "img", "og-default.png"))

    def write(name, text):
        with open(os.path.join(OUT, name), "w", encoding="utf-8") as fh:
            fh.write(text)

    write("index.html", build_front(live, board, stats, treasuries, crypto, money_worldwide))
    write("ask.html", build_ask())
    write("thanks.html", build_thanks())
    write("board.html", build_board(board))

    # The CEBE board is optional by the same contract as the other boards:
    # missing/unreadable JSON costs exactly its own page. Loaded before the
    # treasuries hub so its card can appear there (build_treasuries_hub takes
    # it as an optional arg).
    cebe = None
    if os.path.exists(CEBE_SRC):
        try:
            with open(CEBE_SRC, encoding="utf-8") as fh:
                cebe = json.load(fh)
        except (ValueError, OSError) as exc:
            print("  ! cebe.json unreadable (%s) — skipping the CEBE board" % exc,
                  file=sys.stderr)

    if treasuries and treasuries.get("rows"):
        write("treasuries.html", build_treasuries_hub(treasuries, cebe))
        for category in TREASURY_CATEGORIES:
            write(TREASURY_CATEGORIES[category]["file"],
                  build_treasuries_category(treasuries, category))
    else:
        print("  ! no treasuries board — leaving the last Treasuries pages in place",
              file=sys.stderr)

    if cebe and cebe.get("rows"):
        write("cebe.html", build_cebe(cebe))
    else:
        print("  ! no CEBE board — leaving the last CEBE page in place", file=sys.stderr)

    if crypto and crypto.get("rows"):
        write("crypto.html", build_crypto_heatmap(crypto))
    else:
        print("  ! no crypto heat map — leaving the last Crypto Heat Map page in place",
              file=sys.stderr)

    btc_page = build_bitcoin_board(stats, board) if stats else None
    if btc_page:
        write("bitcoin.html", btc_page)
    else:
        print("  ! no live block height — leaving the last Bitcoin board in place",
              file=sys.stderr)

    # Bitcoin vs. Humanity is optional by the same contract as the Bitcoin
    # Board it shares bitcoin_stats.json with — missing/unreadable stats
    # costs exactly this one page.
    humanity_page = build_humanity_board(stats) if stats else None
    if humanity_page:
        write("humanity.html", humanity_page)
    else:
        print("  ! no live supply figure — leaving the last Bitcoin vs. "
              "Humanity board in place", file=sys.stderr)

    # Money Worldwide is optional by the same contract as every other board:
    # missing/unreadable JSON costs exactly its own pages (the hub, split
    # 2026-09-08 into a hub + one page per section — see MW_SECTIONS).
    if money_worldwide:
        write("money-worldwide.html", build_money_worldwide_hub(money_worldwide))
        for key in MW_SECTION_ORDER:
            write(MW_SECTIONS[key]["file"],
                  build_money_worldwide_section(money_worldwide, key))
    else:
        print("  ! no money-worldwide board — leaving the last Money Worldwide "
              "board in place", file=sys.stderr)

    for e in entries:
        # `live`, not `entries`: "Keep reading" may only advertise published
        # entries, never a draft (unlisted + noindexed by contract).
        page = build_entry_page(e, board, live)
        if page is None:
            print("  ! %s: no live block height in this run — leaving the "
                  "last successful build in place" % e["file"], file=sys.stderr)
            continue
        write(e["file"], page)
    for tag, es in tags.items():
        write("tag-%s.html" % blogkit.tag_slug(tag),
              build_tag_page(tag, es, len(es) >= TAG_INDEX_MIN))
    tl = build_tag_list(tags)
    if tl:
        write("tags.html", tl)
    write("feed.xml", blogkit.build_feed(live, site_name=SITE_NAME, site_url=SITE_URL,
                                         base=BASE, blurb=BLURB))
    write("sitemap.xml", build_sitemap(live, tags))

    _prune_stale_tag_pages(tags)

    indexable = sum(1 for v in tags.values() if len(v) >= TAG_INDEX_MIN)
    print("built /finance/ — %d assets, Bitcoin #%s, data %s"
          % (len(board["assets"]), board.get("btc_rank"), board.get("generated")))
    print("  %d entr%s (%d live), %d tag page%s (%d indexable, %d held back at <%d entries)"
          % (len(entries), "y" if len(entries) == 1 else "ies", len(live),
             len(tags), "" if len(tags) == 1 else "s", indexable,
             len(tags) - indexable, TAG_INDEX_MIN))
    for e in entries:
        print("  %s  %-38s %s" % (e["date"], e["file"], "[DRAFT]" if e["draft"] else ""))
    return 0


def _prune_stale_tag_pages(tags):
    """Delete tag pages whose tag no longer appears on any entry.

    Without this, renaming a tag leaves the old page on disk forever — still
    reachable, still in search, listing entries that have moved on. Scoped hard
    to finance/tag-*.html so it can never reach another publication's output.
    """
    keep = {"tag-%s.html" % blogkit.tag_slug(t) for t in tags}
    for fn in os.listdir(OUT):
        if fn.startswith("tag-") and fn.endswith(".html") and fn not in keep:
            os.remove(os.path.join(OUT, fn))
            print("  (removed stale tag page: %s)" % fn)


def check_entries(entries):
    """Refuse to build on the SEO mistakes that are invisible once shipped.

    Deliberately a hard failure rather than a warning, for the same reason the
    travel builder does it: a warning printed during a build nobody reads is not
    a check. Scoped to what a build can actually judge.
    """
    problems = []
    seen = {}
    for e in entries:
        d = _entry_desc(e)
        if len(d) > META_DESC_MAX:
            problems.append("%s: description is %d chars (max %d) — it would be "
                            "truncated mid-sentence in search results"
                            % (e["slug"], len(d), META_DESC_MAX))
        if not e["tags"]:
            problems.append("%s: no tags" % e["slug"])
        if e["hero"] and not e["hero_alt"]:
            problems.append("%s: hero image has no hero_alt" % e["slug"])
        if d in seen:
            problems.append("%s: identical search description to %s" % (e["slug"], seen[d]))
        seen[d] = e["slug"]
    if problems:
        sys.exit("build refused:\n  " + "\n  ".join(problems))


if __name__ == "__main__":
    sys.exit(main())
